o\":\"Bloquear el acceso a Internet.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Permitir el uso ilimitado de datos personales.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"¿Qué significa \\\"datos personales\\\"?\",\"respuestas\":[{\"texto\":\"Información sobre la cuenta bancaria de una empresa.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Información que identifica a una persona, como nombre y dirección.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Datos sobre el clima.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Estadísticas de ventas de una tienda.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"¿Qué es un consentimiento informado?\",\"respuestas\":[{\"texto\":\"Permitir el uso de datos sin explicación previa.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Aceptar el uso de datos tras recibir información clara y completa.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Negarse a compartir datos personales.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Eliminar datos personales automáticamente.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"¿Qué significa \\\"anonimización\\\" de datos?\",\"respuestas\":[{\"texto\":\"Publicar datos en redes sociales.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Eliminar toda la información de los datos.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"\\r\\n\\r\\nModificar datos para que no puedan ser vinculados a una persona específica.\\r\\n\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Guardar datos en un formato visible.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"¿Qué es un \\\"tercero\\\" en términos de privacidad de datos?\",\"respuestas\":[{\"texto\":\"Una empresa o persona que no tiene relación con el usuario.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Una empresa o persona que recibe datos personales del usuario.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"El dueño de los datos personales.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"El software que guarda los datos.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"¿Qué ley protege la privacidad de los datos en Europa?\",\"respuestas\":[{\"texto\":\"GDPR (Reglamento General de Protección de Datos).\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"COPPA (Ley de Protección de la Privacidad Infantil en Línea).\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"HIPAA (Ley de Portabilidad y Responsabilidad de Seguros de Salud).\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"DMCA (Ley de Derechos de Autor de la Era Digital).\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Qué es un \\\"cookie\\\" en el contexto de la privacidad en línea?\",\"respuestas\":[{\"texto\":\"Un tipo de virus informático.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Un archivo que almacena información sobre el usuario.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Un programa para eliminar spam.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Un sistema de protección contra hackers.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"¿Qué debe hacer una empresa si ocurre una violación de datos?\",\"respuestas\":[{\"texto\":\"Ignorar el incidente.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Informar a las autoridades y a los usuarios afectados.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Vender los datos comprometidos.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Cambiar la contraseña de la cuenta de la empresa.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\" ¿Qué es el derecho al olvido?\",\"respuestas\":[{\"texto\":\"El derecho a ser recordado por las empresas.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"El derecho a que se eliminen datos personales de las bases de datos.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"El derecho a recibir notificaciones.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"El derecho a recibir publicidad personalizada.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":11,\"pregunta\":\"¿Qué se entiende por \\\"minimización de datos\\\"?\",\"respuestas\":[{\"texto\":\"Recoger la mayor cantidad posible de datos.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Recoger los datos necesarios para una finalidad específica.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"No recoger ningún dato.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Compartir datos con tantas empresas como sea posible\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":12,\"pregunta\":\"¿Qué es una política de privacidad?\",\"respuestas\":[{\"texto\":\"Un contrato de ventas.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Explica cómo se manejan y protegen los datos personales.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Una oferta de productos.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Un informe de auditoría.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":13,\"pregunta\":\"¿Qué es el phishing?\",\"respuestas\":[{\"texto\":\"Un juego en línea.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Una técnica fraudulenta para obtener datos personales.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Un método para proteger datos personales.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Un tipo de software antivirus.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":14,\"pregunta\":\"¿Qué implica la portabilidad de datos?\",\"respuestas\":[{\"texto\":\"La transferencia de datos personales de un lugar a otro.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"La creación de copias de seguridad.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La eliminación de datos antiguos.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La venta de datos a otras empresas.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":15,\"pregunta\":\"¿Qué significa \\\"cifrado\\\" de datos?\",\"respuestas\":[{\"texto\":\"Eliminar datos antiguos\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Convertir datos en un código para proteger su privacidad.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Publicar datos en línea.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Compartir datos sin protección.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-03',1,1,14),(274,'Bloque 3','',3,'',3,3,'/multimedia/word/1780511187690-742271151.docx','2026-06-03',1,1,20),(275,'Ernest Hemingway','',3,'https://i.ytimg.com/vi/7f5rqER_6BQ/hqdefault.jpg',1,4,'https://www.youtube.com/watch?v=7f5rqER_6BQ','2026-06-03',1,1,18),(276,'Hacks para escribir un ensayo','',3,'https://i.ytimg.com/vi/108ahyjExro/hqdefault.jpg',1,4,'https://www.youtube.com/watch?v=108ahyjExro','2026-06-03',1,1,18),(277,'Ciudadano digital','',1,'',6,4,'{\"nextpass\":{\"tipogame\":\"SL\",\"titulo\":\"Ciudadano digital\",\"instrucciones\":\"Encuentra en la sopa de letras la palabra faltante al planteamiento o enunciado.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"¿Qué debes mantener siempre seguros en línea?\",\"respuestas\":[{\"texto\":\"datos\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\" ¿Cómo se llama el acto de robar información personal en línea?\",\"respuestas\":[{\"texto\":\"phishing\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"¿Qué palabra describe el comportamiento correcto y responsable en línea?\",\"respuestas\":[{\"texto\":\"etica\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"¿Qué tipo de softwa