pass\":{\"tipogame\":\"VF\",\"titulo\":\"Unidades de medida digital\",\"instrucciones\":\"Analiza lo siguiente y selecciona “V” si la respuesta es verdadera o “F” si es falsa.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\" Un kilobyte (KB) es mayor que un megabyte (MB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\" Un gigabyte (GB) equivale a 1024 megabytes (MB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\" Un terabyte (TB) es igual a 1000 gigabytes (GB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"Un bit es la unidad de medida más pequeña en informática.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"Un byte está compuesto por 10 bits.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"Un petabyte (PB) es mayor que un terabyte (TB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"1 exabyte (EB) es igual a 1024 petabytes (PB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"Un nibble está compuesto por 8 bits\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\" 1 zettabyte (ZB) es igual a 1024 exabytes (EB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\" 1 yottabyte (YB) es menor que 1 terabyte (TB).\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"}]}}','2026-06-03',1,1,14),(288,'Bloque 3','',1,'',3,1,'/multimedia/word/1780511727875-173636690.docx','2026-06-03',1,1,9),(289,'Bloque 1','',1,'',3,2,'/multimedia/word/1780511858717-261456128.docx','2026-06-03',1,1,9),(290,'Bloque 2','',1,'',3,2,'/multimedia/word/1780511884766-289905804.docx','2026-06-03',1,1,9),(291,'Bloque 3','',1,'',3,2,'/multimedia/word/1780511910281-695981709.docx','2026-06-03',1,1,9),(292,'Bloque 1','',3,'',3,3,'/multimedia/word/1780512168630-235031339.docx','2026-06-03',1,1,19),(293,'Bloque 2','',3,'',3,3,'/multimedia/word/1780512189934-15803401.docx','2026-06-03',1,1,19),(294,'Bloque 3','',3,'',3,3,'/multimedia/word/1780512208255-945556020.docx','2026-06-03',1,1,19),(295,'Bloque 1','',3,'',3,3,'/multimedia/word/1780512459061-333615975.docx','2026-06-03',1,1,23),(296,'Bloque 2','',3,'',3,3,'/multimedia/word/1780512482361-146696390.docx','2026-06-03',1,1,23),(297,'Bloque 3','',3,'',3,3,'/multimedia/word/1780512511736-583984959.docx','2026-06-03',1,1,23),(298,'Bloque 1','',3,'',3,1,'/multimedia/word/1780512582104-61032861.docx','2026-06-03',1,1,19),(299,'Bloque 2','',3,'',3,1,'/multimedia/word/1780512604475-848150881.docx','2026-06-03',1,1,19),(300,'La fotosíntesis','',3,'https://i.ytimg.com/vi/CQSVYSznLG8/hqdefault.jpg',1,4,'https://www.youtube.com/watch?v=CQSVYSznLG8','2026-06-03',1,1,20),(301,'Descubriendo el ensayo','',3,'',6,4,'{\"nextpass\":{\"tipogame\":\"VF\",\"titulo\":\"Descubriendo el ensayo\",\"instrucciones\":\"Selecciona la respuesta correcta.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"Un ensayo es un escrito que presenta una opinión personal sobre un tema específico.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"El objetivo principal de un ensayo es simplemente informar sin presentar ningún punto de vista.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"Un ensayo debe seguir estrictamente una estructura de introducción, desarrollo y conclusión.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"En un ensayo, es aceptable incluir opiniones personales sin necesidad de respaldarlas con argumentos.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"La conclusión de un ensayo debe presentar nuevos argumentos para mantener el interés del lector.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"El ensayo académico debe ser objetivo y no reflejar las opiniones del autor.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"El ensayo es un género literario que permite la expresión libre del pensamiento del autor.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"Es recomendable usar un lenguaje complejo y técnico en un ensayo para demostrar conocimiento profundo.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"Un ensayo debe siempre citar las fuentes de información utilizadas para sustentar los argumentos.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"Los ensayos narrativos son una subcategoría de los ensayos que cuentan historias en lugar de argumentar.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-03',1,1,18),(302,'Bloque 1','',3,'',3,1,'/multimedia/word/1780512700814-497446735.docx','2026-06-03',1,1,23),(303,'Bloque 2','',3,'',3,1,'/multimedia/word/1780512739240-827449734.docx','2026-06-03',1,1,23),(304,'Duelo de textos','',3,'',6,4,'{\"nextpass\":{\"tipogame\":\"VF\",\"titulo\":\"Duelo de textos\",\"instrucciones\":\"Selecciona la respuesta correcta referente a la pregunta, planteamiento o enunciado.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"¿Qué tipo de escrito suele ser más breve, la reseña o el comentario crítico?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"¿Cuál de los dos tipos de escrito profundiza más en el análisis del contenido?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"¿Qué escrito generalmente incluye una recomendación final, reseña o comentario crítico?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"¿Cuál de estos escritos puede incluir juicios de valor más subjetivos?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"¿Qué tipo de escrito tiene como objetivo principal informar sobre el contenido?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"¿Qué tipo de escrito analiza en detalle elementos como estilo y estructura?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"¿Cuál de estos escritos es más común encontrar en publicaciones académicas?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Qué tipo de escrito es más adecuado para una revista cultural, reseña o comentario crítico?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"¿Cuál de los dos suele ser más objetivo, la reseña o el comentario crítico?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"¿Qué tipo de escrito podría incluir una evaluación comparativa con otras obras?\",\"respuestas\":[{\"texto\":\"Reseña\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Comentario\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-03