recta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"Es el jefe supremo del ejército, la armada y la fuerza aérea.\",\"respuestas\":[{\"texto\":\"Presidente\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"Colombia, Perú, Nueva Zelanda son ejemplos de un estado\",\"respuestas\":[{\"texto\":\"unitario\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-03',1,1,12),(329,'Derechos fundamentales','',1,'https://i.ytimg.com/vi/mcGrNJzEWo0/hqdefault.jpg',1,4,'https://www.youtube.com/watch?v=mcGrNJzEWo0','2026-06-03',1,1,16),(330,'Los tratados y acuerdos','',1,'',6,4,'{\"nextpass\":{\"tipogame\":\"VF\",\"titulo\":\"Los tratados y acuerdos\",\"instrucciones\":\"Lee con atención y contesta de acuerdo a tu criterio.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"Las normas convencionales se sancionan con la presión social, el rechazo y la crítica. \",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"Las normas jurídicas son dictadas por el poder legislativo.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"Tratado de Libre Comercio de América del Norte se firmó con Estados Unidos, Canadá y México.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"Eliminar el obstáculo al comercio es uno de los objetivos del Tratado de Libre Comercio de América del Norte.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\"