ades.\",\"respuestas\":[{\"texto\":\"humano\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Cómo se considera para la ecología la pérdida de biodiversidad debido a la destrucción y fragmentación de hábitats?\",\"respuestas\":[{\"texto\":\"problema\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-03',1,1,20),(414,'Is the sentence correct or incorrect?','',3,'',6,4,'{\"nextpass\":{\"tipogame\":\"VF\",\"titulo\":\"Is the sentence correct or incorrect?\",\"instrucciones\":\"Mark correct or incorrect for each sentence.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"I like jogg in the mornings better than at night.\",\"respuestas\":[{\"texto\":\"Correct\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Incorrect\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"I hate smelling colognes they make me sneeze.\",\"respuestas\":[{\"texto\":\"Correct\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Incorrect \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"My mother doesn’t enjoy cooking, but she does that anyway.\",\"respuestas\":[{\"texto\":\"Correct\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Incorrect\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"Jose does not love do math exercises and he does alright.\",\"respuestas\":[{\"texto\":\"Correct\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Incorrect\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"I really enjoy going to school it is interesting.\",\"respuestas\":[{\"texto\":\"Correct\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Incorrect\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"I love watching scary movies, they frighten me.\",\"respuestas\":[{\"texto\":\"Correct\",\"e