o\":\"These \",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Those \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"Pass me my keys, ______ on the table.\",\"respuestas\":[{\"texto\":\"this\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"that\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"these \",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"those \",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"Let’s go to the mall to buy _____ 55-inch TV we saw.\",\"respuestas\":[{\"texto\":\"this\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"that\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"these \",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"those \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"Let me introduce you to a friend. _____ is Pablo he is in my class\",\"respuestas\":[{\"texto\":\"This\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"That\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"These \",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Those \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"______ tacos are delicious\",\"respuestas\":[{\"texto\":\"This\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"That\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"These \",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Those \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"You use ____ button here to adjust the sound on the speaker\",\"respuestas\":[{\"texto\":\"this\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"that\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"these \",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"those \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"My board markers are _____ on my desk at the back of the room\",\"respuestas\":[{\"t