stas\":[{\"texto\":\"Genera compromiso\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Aumenta el aislamiento\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Disminuye el compromiso\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fortalece la confrontación\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"¿Qué beneficio adicional puede surgir de la disposición para escuchar y ceder en una negociación?\",\"respuestas\":[{\"texto\":\"Construye relaciones duraderas\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Aumenta la tensión\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Debilita las relaciones interpersonales\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Genera más confrontación\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"¿Cuál es el efecto de escuchar activamente en una negociación?\",\"respuestas\":[{\"texto\":\"Fortalece la empatía\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Aumenta la confrontación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Limita el entendimiento\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Promueve la desconfianza\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"¿Qué se logra al ampliar la comprensión de los problemas en una negociación?\",\"respuestas\":[{\"texto\":\"Identificación de áreas de acuerdo y desacuerdo\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Mayor resistencia\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Menos acuerdo\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Mayor confrontación\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Cómo puede afectar el ceder en ciertos puntos durante la negociación?\",\"respuestas\":[{\"texto\":\"Facilita la resolución de conflictos\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Incrementa la confrontación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Reduce el entendimiento\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fortalece la resistencia\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"¿Qué implica el aumento del compromiso de las partes con el cumplimiento de los términos acordados en una negociación?\",\"respuestas\":[{\"texto\":\"Fortalecimiento de la viabilidad a largo plazo del acuerdo\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Mayor confrontación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Menos responsabilidad compartida\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Reducción de la cooperación\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"¿Qué caracteriza a las interacciones basadas en el respeto mutuo y la cooperación en una negociación?\",\"respuestas\":[{\"texto\":\"Son más beneficiosas para todos\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Son menos duraderas\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Son más confrontativas\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Son menos efectivas\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":11,\"pregunta\":\"¿Qué se logra al establecer expectativas y responsabilidades de cada miembro del equipo durante la construcción de acuerdos?\",\"respuestas\":[{\"texto\":\"Minimiza los malentendidos \",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Aumenta la confusión\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Incrementa la colaboración\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Reduce la productividad\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":12,\"pregunta\":\"¿Qué se fomenta al discutir y negociar las decisiones y acciones a tomar durante la construcción de acuerdos?\",\"respuestas\":[{\"texto\":\"La colaboración y la participación activa\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"La competencia entre los miembros del equipo\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La pasividad de los miembros del equipo\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La disminución de la calidad del trabajo final\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":13,\"pregunta\":\"¿Qué se asegura al llegar a acuerdos sobre la asignación de recursos durante la construcción de acuerdos?\",\"respuestas\":[{\"texto\":\"La optimización de los recursos\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"El desperdicio de recursos\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La duplicación de esfuerzos\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La disminución del rendimiento del equipo\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":14,\"pregunta\":\"¿Qué se motiva al participar en la construcción de acuerdos durante un proyecto?\",\"respuestas\":[{\"texto\":\"El aumento de la responsabilidad\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"La reducción de la responsabilidad\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La disminución del compromiso\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La falta de interés en el éxito del proyecto\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":15,\"pregunta\":\"¿Qué contribuye a mantener un ambiente de trabajo armonioso y productivo durante la construcción de acuerdos?\",\"respuestas\":[{\"texto\":\"El manejo constructivo de conflicto\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"La falta de negociación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"El aumento de la confrontación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"La reducción de la colaboración\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-05',1,1,23),(553,'Regular mis emociones para convivir mejor','',3,'',6,4,'{\"nextpass\":{\"tipogame\":\"SL\",\"titulo\":\"Regular mis emociones para convivir mejor\",\"instrucciones\":\"Encuentra las respuestas a las siguientes preguntas.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"¿Qué se recomienda hacer durante la práctica consciente?\",\"respuestas\":[{\"texto\":\"respirar\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"¿Qué se debe hacer mentalmente mientras observas el movimiento corporal de alguien más?\",\"respuestas\":[{\"texto\":\"escanear\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"¿Qué práctica se sugiere para cambiar el enfoque de emociones negativas?\",\"respuestas\":[{\"texto\":\"gratitud\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"¿Cómo se deben observar los pensamientos y emociones?\",\"respuestas\":[{\"texto\":\"observar\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"¿Qué se recomienda cultivar hacia uno mismo?\",\"respuestas\":[{\"texto\":\"compasion\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"¿Qué tipo de ambiente se fomenta con la comunicación abierta y honesta?\",\"respuestas\":[{\"texto\":\"seguro\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"¿Qué se debe practicar para comprender las motivaciones y preocupaciones de los demás?\",\"respuestas\":[{\"texto\":\"empatia\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Qué se debe buscar en lugar de centrarse en quién tiene la razón?\",\"respuestas\":[{\"texto\":\"solucion\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-05',1,1,23),(554,'Comprendiendo a los demás','',3,'',6,4,'{\"nextpass\":{\"tipogame\":\"VF\",\"titulo\":\"Comprendiendo a los demás\",\"instrucciones\":\"Lee las siguientes afirmaciones y selecciona una de las dos opciones posibles.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"La biología y la neurociencia han demostrado que las estructuras cerebrales y los procesos neuroquímicos asociados con las emociones son similares en hombres y mujeres.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"Las normas de género no pueden influir en cómo las personas expresan sus emociones, pero las emociones en sí mismas no son exclusivas de un género en particular.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"Las diferencias individuales en la personalidad, las experiencias de vida y los factores ambientales pueden influir en cómo una persona experimenta y expresa sus emociones, independientemente de su género.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"Todas las personas, independientemente de su género, son capaces de sentir, gestionar y expresar emociones de manera similar.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"La identidad de género de una persona puede influir en cómo se relaciona con sus propias emociones y cómo los demás perciben y responden a esas emociones.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"Las emociones no son universales, pero la forma en que se expresan puede variar ampliamente entre las personas.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"Reconocer y valorar la diversidad en la experiencia emocional y de género es fundamental para construir sociedades inclusivas y respetuosas.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"Promover la aceptación y el respeto hacia todas las formas de ser y sentir es esencial para fomentar un sentido de pertenencia y apoyo mutuo en nuestras comunidades.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"Comprender y apreciar la diversidad en la forma en que las personas experimentan y expresan emociones es irrelevante para promover la inclusión y la equidad.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"Las normas de género son universales y consistentes en todas las culturas.\",\"respuestas\":[{\"texto\":\"VERDADERO\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"FALSO\",\"esCorrecta\":true,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-05',1,1,23),(555,'Reflexionando sobre mi salud física y mental','',3,'',6,4,'{\"nextpass\":{\"tipogame\":\"OM\",\"titulo\":\"Reflexionando sobre mi salud física y mental\",\"instrucciones\":\"Selecciona la respuesta correcta referente a la pregunta, planteamiento o enunciado.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"¿Cuál es el primer paso para comprender la salud física y mental?\",\"respuestas\":[{\"texto\":\"Educación y conciencia\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Autoevaluación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Escucha activa\",\"esCor