a\":false,\"src\":\"\"},{\"texto\":\"Capital con el desarrollo social. \",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":11,\"pregunta\":\"¿Qué aporta la economía al estudio de las humanidades?\",\"respuestas\":[{\"texto\":\"El estudio de las tendencias de uso.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Producción y los sistemas de mercado. \",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Producción y las tendencias de consumo humano.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Establecer la producción necesaria de insumos.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":12,\"pregunta\":\"¿Cómo se relaciona la política con las humanidades?\",\"respuestas\":[{\"texto\":\"Permite conocer las formas de gobierno.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Permite conocer el pensamiento de los gobernantes.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Permite reconocer las formas de expresión.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Permite conocer las pautas de establecimiento de normas.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":13,\"pregunta\":\"¿Qué papel juega el ser y su existencia en las humanidades?\",\"respuestas\":[{\"texto\":\"El papel central y hegemónico.\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Papel secundario.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"El papel desestabilizador.\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"El papel disruptivo.\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":14,\"pregunta\":\"Es un tema de estudio de las humanidades. \",\"respuestas\":[{\"texto\":\"Pasión\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Dinero\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Mercado\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Complejidad\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":15,\"pregunta\":\"¿Qué papel juega