icación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes impresas\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Qué tipo de fuentes incluyen fotografías, gráficos e infografías?\",\"respuestas\":[{\"texto\":\"Fuentes visuales\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Fuentes en línea\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes de medios de comunicación\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes impresas\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"¿Dónde se pueden encontrar programas de televisión, películas y documentales?\",\"respuestas\":[{\"texto\":\"Fuentes de medios de comunicación\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Fuentes en línea\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes visuales\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes impresas\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"¿Qué tipo de fuentes son los documentos originales, registros históricos y cartas?\",\"respuestas\":[{\"texto\":\"Fuentes primarias\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Fuentes secundarias\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes académicas\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes gubernamentales\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":11,\"pregunta\":\"¿Qué tipo de fuentes son interpretaciones y análisis realizados por expertos sobre fuentes primarias?\",\"respuestas\":[{\"texto\":\"Fuentes secundarias\",\"esCorrecta\":true,\"src\":\"\"},{\"texto\":\"Fuentes primarias\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes académicas\",\"esCorrecta\":false,\"src\":\"\"},{\"texto\":\"Fuentes gubernamentales\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":12,\"pregunta\":\"¿Qué tipo de fuentes incluyen artículos de investigació