:\"reunir\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"¿Qué se hace durante la organización de datos?\",\"respuestas\":[{\"texto\":\"ordenar\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\" ¿Qué se busca durante la exploración de datos?\",\"respuestas\":[{\"texto\":\"detectar\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"¿Qué se realiza en la etapa de interpretación de datos?\",\"respuestas\":[{\"texto\":\"dar\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"¿Qué se busca en la identificación de relaciones?\",\"respuestas\":[{\"texto\":\"definir\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"¿Qué se hace durante la comparación de datos?\",\"respuestas\":[{\"texto\":\"comparar\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"¿Qué se utiliza en el análisis estadístico?\",\"respuestas\":[{\"texto\":\"metodos\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"¿Qué se produce al final del proceso?\",\"respuestas\":[{\"texto\":\"conclusion\",\"esCorrecta\":false,\"src\":\"\"}],\"variante\":\"texto-texto\"}]}}','2026-06-15',1,1,15),(604,'Reflexionando sobre la investigación','',1,'',6,4,'{\"nextpass\":{\"tipogame\":\"VF\",\"titulo\":\"Reflexionando sobre la investigación\",\"instrucciones\":\"Lee las siguientes afirmaciones y selecciona una de las dos opciones posibles.\",\"descripcion\":\"\",\"preguntas\":[{\"numero\":1,\"pregunta\":\"El análisis crítico evalúa los argumentos, evidencias y suposiciones de manera superficial.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":2,\"pregunta\":\"La autoconciencia implica ser consciente de los pensamientos y emociones de los demás.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":3,\"pregunta\":\"La pregunta constante busca explorar diferentes perspectivas y posibilidades.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":4,\"pregunta\":\"La exploración de causas y efectos no busca comprender las conexiones entre diferentes elementos.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":5,\"pregunta\":\"La autoevaluación implica reflexionar sobre acciones y decisiones pasadas.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"},{\"numero\":6,\"pregunta\":\"La empatía no considera las experiencias y perspectivas de otras personas.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":7,\"pregunta\":\"La apertura a la ambigüedad reconoce que todas las situaciones tienen respuestas claras y definitivas.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":8,\"pregunta\":\"El aprendizaje continuo implica estancarse en una sola perspectiva sin buscar nuevas ideas.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":9,\"pregunta\":\"El pensamiento reflexivo puede aplicarse solo en la toma de decisiones personales.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":false},{\"texto\":\"Falso\",\"esCorrecta\":true}],\"variante\":\"texto-texto\"},{\"numero\":10,\"pregunta\":\"El pensamiento reflexivo ayuda a desarrollar una comprensión más profunda del mundo que nos rodea.\",\"respuestas\":[{\"texto\":\"Verdadero\",\"esCorrecta\":true},{\"texto\":\"Falso\",\"esCorrecta\":false}],\"variante\":\"texto-texto\"}]}}','2026-06-15',1,1,15),(605,'Bloque 1','',3,'',3,3,'/multimedia/word/1781809576092-425111387.docx','2026-06-18',1,1,21),(606,'Bloque 2','',3,'',3,3,'/multimedia/word/1781809614603-370171004.docx','2026-06-18',1,1,21),(607,'Bloque 3','',3,'',3,3,'/multimedia/word/1781809636360-575473572.docx','2026-06-18',1,1,21),(608,'Bloque 1','',3,'',3,1,'/multimedia/word/1781809758309-666014626.docx','2026-06-18',1,1,21),(609,'Bloque 2','',3,'',3,1,'/multimedia/word/1781809782491-928232358.docx','2026-06-18',1,1,21),(610,'Bloque 3','',3,'',3,1,'/multimedia/word/1781809800579-511865026.docx','2026-06-18',1,1,21),(611,'Bloque 3','',3,'',3,1,'/multimedia/word/1784828019481-113153890.docx','2026-07-23',1,1,19),(612,'Bloque 1','',1,'',3,1,'/multimedia/word/1784828979072-58434544.docx','2026-07-23',1,1,10),(613,'Bloque 2','',1,'',3,1,'/multimedia/word/1784828998984-547557189.docx','2026-07-23',1,1,10),(614,'Bloque 3','',1,'',3,1,'/multimedia/word/1784829033228-950865202.docx','2026-07-23',1,1,10),(615,'Bloque 1','',1,'',3,2,'/multimedia/word/1786659654714-231202863.docx','2026-08-13',1,1,12),(616,'Bloque 2','',1,'',3,2,'/multimedia/word/1786659690048-316232807.docx','2026-08-13',1,1,12),(617,'Bloque 3','',1,'',3,2,'/multimedia/word/1786659742263-271855495.docx','2026-08-13',1,1,12);
