/*!50003 DROP PROCEDURE IF EXISTS `agregarProductos` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `agregarProductos`(
    IN usuarioId INT,
    IN licenciaId INT
)
BEGIN

    DECLARE existe INT DEFAULT 0;
    DECLARE tiempoLicencia INT DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        SELECT 'ERROR' AS RESPONSE;
    END;

    -- 1️⃣ Validar si ya existe el registro
    SELECT COUNT(*) INTO existe
    FROM CAS_LICENCIAS_USUARIOS
    WHERE LUS_USU_ID = usuarioId
      AND LUS_LIC_ID = licenciaId;

    IF existe > 0 THEN
        SELECT 'EXISTE' AS RESPONSE;

    ELSE

        -- 2 Insertar relación usuario - licencia
        INSERT INTO CAS_LICENCIAS_USUARIOS 
        (LUS_USU_ID, LUS_LIC_ID)
        VALUES 
        (usuarioId, licenciaId);

        -- 3️⃣ Obtener el tiempo de la licencia
        SELECT LIC_TIEMPO 
        INTO tiempoLicencia
        FROM CAS_LICENCIA
        WHERE LIC_ID = licenciaId;

        -- 4️⃣ Si LIC_TIEMPO tiene valor, actualizar fechas
        IF tiempoLicencia IS NOT NULL THEN
            UPDATE CAS_LICENCIA
            SET 
              LIC_FECHA_INICIO = CURDATE(),
              LIC_FECHA_FIN = DATE_ADD(CURDATE(), INTERVAL tiempoLicencia DAY)
            WHERE LIC_ID = licenciaId;
        END IF;

        SELECT 'OK' AS RESPONSE;

    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
