/*!50003 DROP PROCEDURE IF EXISTS `insertarUsuario` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `insertarUsuario`(
  IN u_nombre VARCHAR(45),
  IN u_apellidoP VARCHAR(45),
  IN u_apellidoM VARCHAR(45),
  IN u_correo VARCHAR(100),
  IN u_usuario VARCHAR(45),
  IN u_telefono VARCHAR(45),
  IN u_password VARCHAR(45),
  IN u_fecha DATE,
  IN licenciaId INT
)
BEGIN
  DECLARE correoExiste INT DEFAULT 0;
  DECLARE tiempoLicencia INT DEFAULT NULL;
  DECLARE nuevoUsuarioId INT;

  -- 1. Validar si el correo ya existe
  SELECT COUNT(*) INTO correoExiste
  FROM CAS_USUARIO
  WHERE USU_CORREO = u_correo;

  -- 2. Si el correo ya existe, retornar error
  IF correoExiste > 0 THEN
    SELECT 'CORREO_EXISTE' AS RESPONSE;

  ELSE

    -- A) Insertar Usuario
    INSERT INTO CAS_USUARIO (
      USU_NOMBRE,
      USU_APELLIDOP,
      USU_APELLIDOM,
      USU_CORREO,
      USU_USUARIO,
      USU_TELEFONO,
      USU_PASSWORD,
      USU_FECHA_REGISTRO
    )
    VALUES (
      u_nombre,
      u_apellidoP,
      u_apellidoM,
      u_correo,
      u_usuario,
      u_telefono,
      u_password,
      u_fecha
    );

    -- Guardamos el ID del usuario recién creado
    SET nuevoUsuarioId = LAST_INSERT_ID();

    -- B) Insertar relación Usuario - Licencia
    INSERT INTO CAS_LICENCIAS_USUARIOS (LUS_USU_ID, LUS_LIC_ID)
    VALUES (nuevoUsuarioId, licenciaId);

    -- C) Obtener el tiempo de la licencia
    SELECT LIC_TIEMPO 
    INTO tiempoLicencia
    FROM CAS_LICENCIA
    WHERE LIC_ID = licenciaId;

    -- D) Si LIC_TIEMPO NO es NULL, actualizar fechas
    IF tiempoLicencia IS NOT NULL THEN
        UPDATE CAS_LICENCIA
        SET 
          LIC_FECHA_INICIO = u_fecha,
          LIC_FECHA_FIN = DATE_ADD(u_fecha, INTERVAL tiempoLicencia DAY)
        WHERE LIC_ID = licenciaId;
    END IF;

    SELECT 'OK' AS RESPONSE, nuevoUsuarioId AS USER_ID;

  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
