/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `LOGIN_USUARIO_ADMIN`(
    IN p_usuario   VARCHAR(100),
    IN p_password  VARCHAR(100)
)
BEGIN
    -- Actualizar último acceso del usuario que coincide
    UPDATE CAS_USUARIO_ADMIN
    SET UAD_ULTIMO_ACCESO = NOW()
    WHERE UAD_USUARIO  = p_usuario
      AND UAD_PASSWORD = p_password
      AND UAD_STATUS   = 1;
    -- Devolver datos del usuario (incluido último acceso)
    SELECT
        UAD_ID,
        UAD_NOMBRE,
        UAD_USUARIO,
        UAD_TIPO,
        UAD_STATUS,
        UAD_ULTIMO_ACCESO
    FROM CAS_USUARIO_ADMIN
    WHERE UAD_USUARIO  = p_usuario
      AND UAD_PASSWORD = p_password
      AND UAD_STATUS   = 1;
END ;;
DELIMITER ;
