        m.MUL_SBT_ID,
        m.MUL_ENLACE,
        m.MUL_FECHA_CREACION,
        m.MUL_STATUS,
        m.MUL_UAD_ID,
        m.MUL_MAT_ID,
        mat.MAT_NOMBRE AS MUL_MATERIA_NOMBRE
    FROM CAS_MULTIMEDIA m
    LEFT JOIN CAS_MATERIA mat ON m.MUL_MAT_ID = mat.MAT_ID
    WHERE m.MUL_TIPO = 8
      AND m.MUL_STATUS = 1
    ORDER BY m.MUL_FECHA_CREACION DESC;
END ;;
DELIMITER ;
