CREATE DEFINER=`root`@`%` PROCEDURE `mostrarGradosPorLicencia`(
IN p_lic_id INT
)
BEGIN
SELECT DISTINCT
        g.GRA_ID,
        g.GRA_NUMERO,
        g.GRA_NOMBRE,
        g.GRA_SUB_ID,
        g.GRA_STATUS
    FROM CAS_LICENCIA l
    INNER JOIN CAS_PAQUETE pq
        ON pq.PAQ_ID = l.LIC_PAQ_ID
    INNER JOIN CAS_PRODUCTOS pr
        ON FIND_IN_SET(
             pr.PRO_ID,
             REPLACE(REPLACE(REPLACE(pq.PAQ_PRODUCTOS, '[', ''), ']', ''), ' ', '')
           ) > 0
       AND pr.PRO_TIPO = 'ebook'
    INNER JOIN CAS_GRADO g
        ON g.GRA_ID = pr.PRO_GRA_ID
    WHERE l.LIC_ID = p_lic_id
    ORDER BY g.GRA_NUMERO;
END ;;
DELIMITER ;
