CREATE DEFINER=`root`@`%` PROCEDURE `mostrarGradosSubtipos`(
    IN subtipo INT
)
BEGIN
    SELECT MUL_GRA_ID
    FROM BD_CASA.CAS_MULTIMEDIA
    WHERE MUL_SBT_ID = subtipo
    GROUP BY MUL_GRA_ID
    HAVING SUM(CASE WHEN MUL_STATUS = 1 THEN 1 ELSE 0 END) > 0;
END ;;
