CREATE DEFINER=`root`@`%` PROCEDURE `sp_existe_correo_usuario`(
    IN correo VARCHAR(45)
)
BEGIN
    IF EXISTS (SELECT 1 FROM CAS_USUARIO WHERE USU_CORREO = correo) THEN
        SELECT 
            'SI' AS RESPONSE,
            USU_NOMBRE,
            USU_USUARIO,
            USU_PASSWORD
        FROM CAS_USUARIO
        WHERE USU_CORREO = correo;
    ELSE
        SELECT 
            'NO' AS RESPONSE,
            NULL AS USU_NOMBRE,
            NULL AS USU_USUARIO,
            NULL AS USU_PASSWORD;
    END IF;
END ;;
DELIMITER ;
