CREATE DEFINER=`root`@`%` PROCEDURE `sp_existe_licencia`(
	IN tipo VARCHAR(100),
    IN licencia VARCHAR(100)
)
BEGIN
    SELECT 
        CASE 
            WHEN COUNT(*) > 0 THEN 'SI'
            ELSE 'NO'
        END AS RESPONSE,
        MAX(LIC_ID) AS LIC_ID
    FROM CAS_LICENCIA
    WHERE LIC_LICENCIA = licencia
      AND LIC_TIPO = tipo AND LIC_STATUS = 1;
END ;;
DELIMITER ;
