CREATE DEFINER=`root`@`%` PROCEDURE `sp_login_usuario`(
  IN p_usuario VARCHAR(50),
  IN p_password VARCHAR(100)
)
BEGIN
  SELECT 
    USU_ID,
    USU_NOMBRE,
    USU_USUARIO,
    'OK' AS RESPONSE
  FROM CAS_USUARIO
  WHERE USU_USUARIO = p_usuario
  AND USU_PASSWORD = p_password
  LIMIT 1;
END ;;
